"use client";

import { useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  Book,
  Code,
  Database,
  Globe,
  Network,
  Search,
  Terminal,
  ChevronRight,
  Menu,
  X,
  FileJson,
  FileText,
  Zap,
  Shield,
  Wifi,
} from "lucide-react";
import GitHubIcon from "@/components/ui/GitHubIcon";

const docsNav = [
  {
    category: "Getting Started",
    items: [
      { href: "/docs", label: "Introduction", icon: Book },
      { href: "/docs/quick-start", label: "Quick Start", icon: Zap },
      { href: "/docs/installation", label: "Installation", icon: Terminal },
    ],
  },
  {
    category: "API Reference",
    items: [
      { href: "/docs/api/countries", label: "Countries API", icon: Globe },
      { href: "/docs/api/asn", label: "ASN API", icon: Network },
      { href: "/docs/api/search", label: "Search API", icon: Search },
    ],
  },
  {
    category: "Data Formats",
    items: [
      { href: "/docs/formats/json", label: "JSON Format", icon: FileJson },
      { href: "/docs/formats/csv", label: "CSV Format", icon: FileText },
      { href: "/docs/formats/cidr", label: "CIDR Notation", icon: Wifi },
    ],
  },
  {
    category: "Guides",
    items: [
      {
        href: "/docs/guides/ip-lookup",
        label: "IP Lookup Guide",
        icon: Shield,
      },
      {
        href: "/docs/guides/asn-lookup",
        label: "ASN Lookup Guide",
        icon: Network,
      },
      { href: "/docs/guides/export", label: "Export Data", icon: Database },
    ],
  },
];

export default function DocsLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  return (
    <div className="min-h-screen">
      <div className="lg:hidden sticky top-[74px] z-40 bg-[#05070a] border-b border-[rgba(34,229,122,.06)] px-4 py-3">
        <button
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          className="flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors"
        >
          {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          <span className="font-mono text-sm">Documentation</span>
        </button>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <aside
          className={`lg:w-72 flex-shrink-0 ${isMobileMenuOpen ? "block" : "hidden lg:block"}`}
        >
          <div className="lg:sticky lg:top-[90px] space-y-6">
            <div className="hidden lg:block">
              <h2 className="text-xs font-mono font-bold text-[#22e57a] tracking-widest uppercase">
                Documentation
              </h2>
              <p className="text-[#6f8a7d] text-sm font-mono mt-1">
                Learn how to use the IP Database
              </p>
            </div>

            <nav className="space-y-4">
              {docsNav.map((category) => (
                <div key={category.category}>
                  <h3 className="text-[10px] font-mono font-bold text-[#4f6459] uppercase tracking-wider mb-2">
                    {category.category}
                  </h3>
                  <ul className="space-y-0.5">
                    {category.items.map((item) => {
                      const isActive = pathname === item.href;
                      return (
                        <li key={item.href}>
                          <Link
                            href={item.href}
                            className={`flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm font-mono transition-all duration-200 ${
                              isActive
                                ? "bg-[rgba(34,229,122,.08)] text-[#22e57a] border border-[rgba(34,229,122,.15)]"
                                : "text-[#6f8a7d] hover:text-[#c6d2ca] hover:bg-[rgba(34,229,122,.04)]"
                            }`}
                            onClick={() => setIsMobileMenuOpen(false)}
                          >
                            <item.icon
                              size={15}
                              className={
                                isActive ? "text-[#22e57a]" : "text-[#4f6459]"
                              }
                            />
                            <span>{item.label}</span>
                            {isActive && (
                              <ChevronRight
                                size={12}
                                className="ml-auto text-[#22e57a]"
                              />
                            )}
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              ))}
            </nav>

            <div className="pt-4 border-t border-[rgba(34,229,122,.06)]">
              <a
                href="https://github.com/inject3r/ip-address-database"
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors text-sm font-mono"
              >
                <GitHubIcon size={16} />
                <span>View on GitHub</span>
              </a>
            </div>
          </div>
        </aside>

        <main className="flex-1 min-w-0">
          <div className="bg-[#070b09]/60 border border-[rgba(34,229,122,.08)] rounded-xl p-6 md:p-8">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}
